#include <bits/stdc++.h>
using namespace std;

const int INF = 0x3f3f3f3f;
const int MAXN = 410;
const int dx[4] = {-1, 0, 1, 0};
const int dy[4] = {0, 1, 0, -1};

int n, t;
vector<string> g, h;
int tim[12][12], dis[12][12];

struct Edge {
    int to, rev, cap;
};
vector<Edge> graph[MAXN];

void addEdge(int u, int v, int c) {
    graph[u].push_back({v, (int)graph[v].size(), c});
    graph[v].push_back({u, (int)graph[u].size() - 1, 0});
}

bool bfsLevel(int s, int t, vector<int>& level) {
    fill(level.begin(), level.end(), -1);
    queue<int> q;
    level[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (const Edge& e : graph[u]) {
            if (e.cap > 0 && level[e.to] == -1) {
                level[e.to] = level[u] + 1;
                q.push(e.to);
            }
        }
    }
    return level[t] != -1;
}

int sendFlow(int u, int t, int pushed, vector<int>& level, vector<int>& ptr) {
    if (u == t) return pushed;
    for (int &cid = ptr[u]; cid < (int)graph[u].size(); ++cid) {
        Edge &e = graph[u][cid];
        if (level[e.to] == level[u] + 1 && e.cap > 0) {
            int tr = sendFlow(e.to, t, min(pushed, e.cap), level, ptr);
            if (tr > 0) {
                e.cap -= tr;
                graph[e.to][e.rev].cap += tr;
                return tr;
            }
        }
    }
    return 0;
}

int maxFlow(int s, int t) {
    int total = 0;
    vector<int> level(MAXN);
    while (bfsLevel(s, t, level)) {
        vector<int> ptr(MAXN, 0);
        while (true) {
            int pushed = sendFlow(s, t, INF, level, ptr);
            if (pushed == 0) break;
            total += pushed;
        }
    }
    return total;
}

bool inside(int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < n;
}

void bfs1(int sx, int sy) {
    memset(tim, 0x3f, sizeof(tim));
    queue<int> q;
    q.push(sx * 10 + sy);
    tim[sx][sy] = 0;
    while (!q.empty()) {
        int x = q.front() / 10, y = q.front() % 10;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dx[k], ny = y + dy[k];
            if (inside(nx, ny) && g[nx][ny] >= '0' && g[nx][ny] <= '9' && tim[nx][ny] > tim[x][y] + 1) {
                tim[nx][ny] = tim[x][y] + 1;
                q.push(nx * 10 + ny);
            }
        }
    }
}

void bfs2(int sx, int sy) {
    memset(dis, 0x3f, sizeof(dis));
    queue<int> q;
    q.push(sx * 10 + sy);
    dis[sx][sy] = 0;
    while (!q.empty()) {
        int x = q.front() / 10, y = q.front() % 10;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dx[k], ny = y + dy[k];
            if (inside(nx, ny) && h[nx][ny] >= '0' && h[nx][ny] <= '9' && dis[nx][ny] > dis[x][y] + 1) {
                if (tim[nx][ny] >= dis[x][y] + 1) {
                    dis[nx][ny] = dis[x][y] + 1;
                    if (tim[nx][ny] > dis[nx][ny])
                        q.push(nx * 10 + ny);
                }
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> t;
    g.resize(n);
    h.resize(n);
    for (int i = 0; i < n; ++i) cin >> g[i];
    for (int i = 0; i < n; ++i) cin >> h[i];

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (g[i][j] == 'Z')
                bfs1(i, j);

    int S = 0, T = n * n * 2 + 1;
    for (int i = 0; i <= T; ++i) graph[i].clear();

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            if (g[i][j] > '0' && g[i][j] <= '9')
                addEdge(S, i * n + j + 1, g[i][j] - '0');
            if (h[i][j] > '0' && h[i][j] <= '9')
                addEdge(n * n + i * n + j + 1, T, h[i][j] - '0');
        }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (g[i][j] > '0' && g[i][j] <= '9') {
                bfs2(i, j);
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y)
                        if (h[x][y] > '0' && h[x][y] <= '9' && dis[x][y] <= t)
                            addEdge(i * n + j + 1, n * n + x * n + y + 1, INF);
            }

    cout << maxFlow(S, T) << '\n';
    return 0;
}
